head.script:
scwin.screenId = "jldmgt90400";

///////// 1. 변수 및 선언 영역 /////////


scwin.contnId = undefined;

scwin.notiObjSysCode = undefined;

scwin.vScrenID = "ULDSTF90400.gfm";

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.url = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.listSync();
        $c.util.getComponent('slc_MxCombo1').setSelectedIndex(0);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldmgt90400.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_noti_obj_sys_cd = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsNotiObjSysCd')) : $c.util.getComponent('dtsNotiObjSysCd');

scwin.dts_noticeList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsNoticeList')) : $c.util.getComponent('dtsNoticeList');

scwin.MxDataSet_code1 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('MxDataSetCode1')) : $c.util.getComponent('MxDataSetCode1');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldmgt90400.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name scwin.dts_noticeList_onloadcompleted
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowcount
 * @returns
 * @hidden N
*/
scwin.dts_noticeList_onloadcompleted = function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_noticeList_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    void 0;
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.MxGrid_2_ondblclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param row colid
 * @returns
 * @hidden N
*/
scwin.MxGrid_2_ondblclick = async function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin MxGrid_2_ondblclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (colid === 'SAVE_FILE_NM') {
            const screnId = scwin.dts_noticeList.getCellData(row, "SCREN_ID");
            await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /filedownload.do?SCREN_ID=). 전환 대상 화면이 확정되면 연결됩니다.') + screnId + "&gubun=35";
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldmgt90400.MxGrid_2_ondblclick' }); }
};

/**
 * @event
 * @name scwin.bnt_Select_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.bnt_Select_onclick = async function () {
    try {
        /* sdd-asis-lifecycle:begin bnt_Select_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.listSync();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldmgt90400.bnt_Select_onclick' }); }
};

/**
 * @event
 * @name scwin.keyword_onkeydown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.keyword_onkeydown = async function () {
    try {
        /* sdd-asis-lifecycle:begin keyword_onkeydown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.util.getKeyCode(event) === "13") {
            await scwin.listSync();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldmgt90400.keyword_onkeydown' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_MxDataSet_code1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_MxDataSet_code1 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_script_MxDataSet_code1", unresolved: "action:self_submit:tx_script_MxDataSet_code1" };
};

/**
 * @method
 * @name scwin.tx_script_dts_noticeList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_noticeList = async function () {
    $c.util.getComponent("dma_scriptDtsNoticeListReq").set("SCREN_ID", "ULDSTF90400.gfm");
    $c.util.getComponent("dma_scriptDtsNoticeListReq").set("Condition2", "3");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — ipt_keyword, Condition1", unresolved: "query_param:ipt_keyword,Condition1" };
    const sbmOptions = {
        id: "tx_script_dts_noticeList",
        method: "post",
        action: "/NoticeContent.do",
        ref: "dma_scriptDtsNoticeListReq",
        target: "dtsNoticeList=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_noticeList_onloaderror'] === 'function') ? scwin['dts_noticeList_onloaderror'] : (typeof scwin['dts_noticeList_onfail'] === 'function') ? scwin['dts_noticeList_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_noticeList_onloadcompleted'] === 'function') ? scwin['dts_noticeList_onloadcompleted'] : ((typeof scwin['dts_noticeList_onsuccess'] === 'function') ? scwin['dts_noticeList_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsNoticeList'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldmgt90400.tx_script_dts_noticeList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.listSync = async function () {
    /* sdd-asis-lifecycle:begin fn_list_sync — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const KeyWord = ipt_keyword.value;
    const Condition1 = slc_MxCombo1.valueOfIndex("VALUE", slc_MxCombo1.Index);
    scwin.url = "/NoticeContent.do?method=listHelpContent";
    scwin.url += "&SCREN_ID=" + scwin.vScrenID;
    scwin.url += "&keyword=" + KeyWord;
    scwin.url += "&Condition1=" + Condition1;
    scwin.url += "&Condition2=3";

    await scwin.tx_script_dts_noticeList();
    void 0;
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_code1_sync = scwin.tx_script_MxDataSet_code1;
